  "identity": {
    "procedure_type": "self_executing_ai_nlep_meta_procedure",
    "execution_basis": "Execute this JSON directly. The construction_pipeline is the operative procedure for constructing or revising an AI-NLEP.",
    "principal_output": "ai_nlep",
    "self_execution_rule": "Do not merely summarize or restate this JSON when invoked to construct an NLEP; execute applicable operations, audits, repairs, and completion gates."
  },
  "definitions": [
    {
      "term_id": "RD1",
      "term": "AI-NLE",
      "definition": "An AI natural-language executor: an AI system capable of interpreting natural-language instructions and translating them into actions, reasoning, tool use, or outputs.",
