        {
          "term": "deterministic executor",
          "distinction": "An AI-NLE may exercise interpretation and bounded judgment; a deterministic executor follows fixed machine semantics."
        }
      ]
    },
    {
      "term_id": "RD2",
      "term": "NLEP",
      "definition": "A natural-language-executable procedure: a procedure expressed primarily in natural language and intended for execution by a natural-language-capable executor.",
      "distinguished_from": [
        {
          "term": "prompt",
          "distinction": "A prompt may request an outcome without defining an executable procedure; an NLEP specifies procedural behavior."
        }
      ]
    },
    {
      "term_id": "RD3",
      "term": "specification_gap",
      "definition": "The difference between the operation intended by a procedure writer and the operation constructed by the executor from the written instruction.",
