    {
      "term_id": "RD6",
      "term": "invariant",
      "definition": "A condition that must remain true throughout every execution state to which it applies.",
      "distinguished_from": []
    },
    {
      "term_id": "RD7",
      "term": "authority",
      "definition": "A source whose contents determine a relevant fact, rule, state, or requirement.",
      "distinguished_from": [
        {
          "term": "evidence",
          "distinction": "Authority establishes what source governs a subject; evidence establishes whether a condition is true."
