    {
      "term_id": "RD8",
      "term": "state_element",
      "definition": "Information whose current value materially affects execution.",
      "distinguished_from": [
        {
          "term": "input",
          "distinction": "An input is supplied to the procedure; a state element is a current execution condition that may be initialized, retrieved, or updated."
        }
      ]
    },
    {
      "term_id": "RD9",
      "term": "transition_rule",
      "definition": "A rule determining movement from one execution state or procedure step to another.",
      "distinguished_from": []
    },
    {
      "term_id": "RD10",
      "term": "verification_rule",
      "definition": "A rule specifying evidence and criteria used to determine whether a requirement has been satisfied.",
      "distinguished_from": [
        {
          "term": "completion condition",
          "distinction": "A completion condition governs termination; a verification rule establishes whether a requirement is satisfied."
