  "inference_and_discretion_policy": {
    "default_policy": "No consequential omission or ambiguity is filled silently. Classify it as literal, retrieve, infer_bounded, choose, clarify, or block and record the basis when the choice can affect execution.",
    "dispositions": {
      "literal": "Apply the specified requirement without substituting another interpretation or method.",
      "retrieve": "Obtain the required information from the identified authoritative source.",
      "infer_bounded": "Infer only within explicitly stated semantic or operational bounds.",
      "choose": "Select among materially equivalent alternatives when the procedure intentionally delegates the choice.",
      "clarify": "Request clarification when materially different unresolved interpretations remain and clarification is available and appropriate.",
      "block": "Do not continue when unresolved information makes correct execution impossible or materially unreliable."
    },
    "decision_rules": [
      {
        "rule_id": "IDR1",
        "when": "The governing source explicitly states the operation or meaning and no unresolved conflict applies.",
        "disposition": "literal",
        "rule": "Apply the stated semantics without substituting a preferred method, inferred goal, or related result."
      },
      {
        "rule_id": "IDR2",
        "when": "A consequential fact, current state, rule, or configuration has an identified available authoritative source.",
        "disposition": "retrieve",
        "rule": "Retrieve/inspect that source before using the value."
      },
      {
        "rule_id": "IDR3",
        "when": "Information is missing but the governing procedure explicitly defines an inference domain, default rule, range, or transformation.",
        "disposition": "infer_bounded",
        "rule": "Infer only inside the stated bounds and expose the inferred value/basis when consequential."
      },
      {
        "rule_id": "IDR4",
        "when": "Multiple alternatives are explicitly permitted and their differences are immaterial to required success.",
        "disposition": "choose",
        "rule": "Select any materially equivalent alternative without asking the giver to decide."
      },
      {
        "rule_id": "IDR5",
        "when": "Multiple materially different interpretations remain, clarification is available, and execution need not continue immediately.",
        "disposition": "clarify",
        "rule": "Ask only for the unresolved information needed to distinguish the material alternatives."
      },
      {
        "rule_id": "IDR6",
        "when": "Correct execution materially depends on unresolved information and neither authority, bounded inference, authorized choice, nor clarification can resolve it.",
        "disposition": "block",
        "rule": "Do not continue across the unresolved dependency; return the blocking condition."
      },
      {
        "rule_id": "IDR7",
        "when": "A prescribed operation's apparent result already exists.",
        "disposition": "literal",
        "rule": "Perform the prescribed operation unless an explicit procedure branch authorizes skip, alternative, equivalence, or idempotent short-circuit."
