  "transition_model": {
    "states": [
      {
        "state": "constructing",
        "meaning": "Core semantic objects are being built."
      },
      {
        "state": "evaluating",
        "meaning": "Property, completeness, adversarial, verification, or cross-property audits are running."
      },
      {
        "state": "repairing",
        "meaning": "One or more repairable material defects are being corrected."
      },
      {
        "state": "awaiting_authority",
        "meaning": "Execution requires authoritative retrieval or clarification before a dependent operation may continue."
      },
      {
        "state": "incomplete",
        "meaning": "Required work remains and can still be performed with available information/capabilities."
      },
      {
        "state": "blocked",
        "meaning": "A materially necessary unresolved condition cannot be resolved with available information/capabilities."
      },
      {
        "state": "complete",
        "meaning": "All complete_when conditions hold and completion provenance is established."
      },
      {
        "state": "failed",
        "meaning": "A procedure-defined terminal failure condition occurred and no retry/recovery branch remains."
      },
      {
        "state": "transferred",
        "meaning": "Responsibility/control was explicitly handed to another executor/process under a procedure-authorized transfer rule."
      }
    ],
    "transitions": [
      {
        "transition_id": "T1",
        "from": "constructing",
        "to": "awaiting_authority",
        "condition": "A consequential fact or rule requires retrieval/clarification before dependent construction.",
        "actions": [
          "Suspend only dependent operations.",
          "Retrieve authority or obtain clarification if available."
        ],
        "prohibited_if": []
      },
      {
        "transition_id": "T2",
        "from": "awaiting_authority",
        "to": "constructing",
        "condition": "The required authority/clarification resolves the dependency.",
        "actions": [
          "Record the resolved value and basis.",
          "Resume dependent construction."
        ],
        "prohibited_if": []
      },
      {
        "transition_id": "T3",
        "from": "awaiting_authority",
        "to": "blocked",
        "condition": "The dependency is material and cannot be resolved using available information/capabilities.",
        "actions": [
          "Record the blocking condition and affected requirements."
        ],
        "prohibited_if": [
          "An authorized bounded inference or materially equivalent choice remains available."
        ]
      },
      {
        "transition_id": "T4",
        "from": "constructing",
        "to": "evaluating",
        "condition": "A complete candidate exists for the current construction cycle.",
        "actions": [
          "Run P1-P20 audit.",
          "Run semantic-class completeness audit.",
          "Run adversarial interpretation test.",
          "Run cross-property audit."
        ],
        "prohibited_if": [
          "Known required construction operations have not yet been attempted."
        ]
      },
      {
        "transition_id": "T5",
        "from": "evaluating",
        "to": "repairing",
        "condition": "A repairable material defect is found.",
        "actions": [
          "Record defect, affected properties, and repair scope.",
          "Invalidate affected prior PASS results."
        ],
        "prohibited_if": []
      },
      {
        "transition_id": "T6",
        "from": "repairing",
        "to": "evaluating",
        "condition": "The selected repair has been applied.",
        "actions": [
          "Re-run every affected audit.",
          "Retest repaired wording/structure adversarially where applicable."
        ],
        "prohibited_if": []
      },
      {
        "transition_id": "T7",
        "from": "evaluating",
        "to": "constructing",
        "condition": "An audit reveals omitted required construction that can still be performed.",
        "actions": [
          "Return to the required construction operation and update the operation ledger."
        ],
        "prohibited_if": []
      },
      {
        "transition_id": "T8",
        "from": "evaluating",
        "to": "incomplete",
        "condition": "Required work remains, is feasible, but cannot be completed within the current execution boundary for a non-blocking reason.",
        "actions": [
          "Return the outstanding work without claiming completion."
        ],
        "prohibited_if": [
          "The remaining work can and must still be performed in the same execution under the procedure."
        ]
      },
      {
        "transition_id": "T9",
        "from": "evaluating",
        "to": "blocked",
        "condition": "A materially necessary defect or dependency is unresolvable with available information/capabilities.",
        "actions": [
          "Record unresolved defect, authority gap/capability gap, and blocked requirements."
        ],
        "prohibited_if": [
          "A repair or authorized resolution remains available."
        ]
      },
      {
        "transition_id": "T10",
        "from": "evaluating",
        "to": "complete",
        "condition": "Every complete_when condition holds, all required audits PASS, invariants hold, no known material defect remains, and the current self-execution record covers every required non-skipped operation.",
        "actions": [
          "Set terminal status complete.",
          "Emit the return contract."
        ],
        "prohibited_if": [
          "Any operation is not_started, attempted, or failed when completion requires it.",
          "Any required audit is unevaluated/DEFECT_FOUND/BLOCKED.",
          "Any invariant is violated.",
          "Any completion basis relies on unauthorized state-equivalence inference."
        ]
      },
      {
        "transition_id": "T11",
        "from": "constructing",
        "to": "constructing",
        "condition": "A procedure-authorized optional/conditional branch is not applicable.",
        "actions": [
          "Mark its operation skipped_by_procedure with the explicit authorization basis.",
          "Continue along the authorized branch."
        ],
        "prohibited_if": [
          "The skip basis is inferred rather than explicit."
        ]
      },
      {
        "transition_id": "T12",
        "from": "constructing",
        "to": "blocked",
        "condition": "A required capability/interface is unavailable and no explicit alternative, defer, or transfer path is authorized.",
        "actions": [
          "Record the unavailable capability and affected operation.",
          "Do not simulate or claim the operation."
        ],
        "prohibited_if": [
          "An authorized alternative or transfer path remains available."
        ]
      },
      {
        "transition_id": "T13",
        "from": "constructing or evaluating",
        "to": "failed",
        "condition": "A procedure-defined terminal operation failure occurs, retry/recovery is exhausted or not permitted, and the condition is failure rather than a missing dependency.",
        "actions": [
          "Record the failed operation, evidence, and terminal failure basis.",
          "Do not claim completion."
        ],
        "prohibited_if": [
          "A required repair/retry path remains available."
        ]
      },
      {
        "transition_id": "T14",
        "from": "constructing or evaluating",
        "to": "transferred",
        "condition": "The procedure explicitly authorizes transfer of specified responsibility to another executor/process and all transfer preconditions hold.",
        "actions": [
          "Record transferred scope, destination, handoff state, and remaining responsibility.",
          "Do not claim the transferred operation was performed by the current executor."
        ],
        "prohibited_if": [
          "Transfer is merely inferred as convenient rather than authorized."
        ]
      }
    ],
    "retry_rules": [
      {
        "retry_id": "RR1",
        "applies_to": "repairable specification defects",
        "rule": "Repair one or a coherent set of interacting defects, then re-run affected audits; continue until PASS or blocked.",
        "stop_condition": "No known repairable material defect remains, or a materially necessary defect becomes blocked."
      },
      {
        "retry_id": "RR2",
        "applies_to": "authority retrieval",
        "rule": "Retry only when a transient retrieval/interface failure exists and the procedure permits another attempt.",
        "stop_condition": "Authority is retrieved, retry limit/availability is exhausted, or an alternative explicit branch applies."
      },
      {
        "retry_id": "RR3",
        "applies_to": "interface invocation",
        "rule": "A failed invocation remains failed/attempted until a subsequent actual invocation succeeds; do not convert failure to success from expected state.",
        "stop_condition": "Operation succeeds under its own completion semantics or transition rules require failure/blocking."
      },
      {
        "retry_id": "RR4",
        "applies_to": "adversarial interpretation",
        "rule": "After wording repair, re-run the interpretation test on the repaired rule and affected neighboring rules.",
        "stop_condition": "No known unacceptable material interpretation remains or unresolved ambiguity causes block."
      }
    ],
